SELECT 
FROM kitchen_binding
WHERE kitchen_id = #{kitchenId}
  AND diner_user_id = #{dinerUserId}
  AND status = 'PENDING'
LIMIT 1

SELECT 
FROM kitchen_binding
WHERE kitchen_id = #{kitchenId}
  AND diner_user_id = #{dinerUserId}
ORDER BY create_time DESC
LIMIT 1

SELECT 
FROM kitchen_binding
WHERE kitchen_id = #{kitchenId}

      AND status = #{status}

ORDER BY applied_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM kitchen_binding
WHERE kitchen_id = #{kitchenId}

      AND status = #{status}

SELECT 
FROM kitchen_binding
WHERE 1 = 1

      AND kitchen_id = #{kitchenId}


      AND status = #{status}

ORDER BY applied_at DESC
LIMIT #{limit} OFFSET #{offset}

